import { useState } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const SUMMARY: { label: string; key: keyof RegistrationValues }[] = [
  { label: 'Имя', key: 'name' },
  { label: 'Электронная почта', key: 'email' },
  { label: 'Телефон', key: 'phone' },
  { label: 'Город', key: 'city' },
  { label: 'Улица и дом', key: 'street' },
  { label: 'Индекс', key: 'zip' },
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);

  const isLast = step === STEPS.length - 1;

  const update = (key: keyof RegistrationValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const { value } = event.target;
    setValues((current) => ({ ...current, [key]: value }));
  };

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (isLast) {
          onSubmit(values);
        } else {
          setStep((current) => Math.min(current + 1, STEPS.length - 1));
        }
      }}
      style={{ display: 'flex', flexDirection: 'column', gap: 24 }}
    >
      <JxStepper steps={STEPS} current={step} />

      <div style={{ display: 'grid', gap: 16 }}>
        {step === 0 && (
          <>
            <JxInputField
              label="Имя"
              required
              autoComplete="name"
              value={values.name}
              onChange={update('name')}
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              autoComplete="email"
              helperText="Отправим письмо для подтверждения"
              value={values.email}
              onChange={update('email')}
            />
            <JxInputField
              label="Телефон"
              type="tel"
              prefix="+7"
              autoComplete="tel"
              value={values.phone}
              onChange={update('phone')}
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField
              label="Город"
              required
              autoComplete="address-level2"
              value={values.city}
              onChange={update('city')}
            />
            <JxInputField
              label="Улица и дом"
              required
              autoComplete="street-address"
              value={values.street}
              onChange={update('street')}
            />
            <JxInputField
              label="Индекс"
              inputMode="numeric"
              autoComplete="postal-code"
              value={values.zip}
              onChange={update('zip')}
            />
          </>
        )}

        {step === 2 && (
          <dl style={{ display: 'grid', gap: 12, margin: 0 }}>
            {SUMMARY.map((row) => (
              <div key={row.key} style={{ display: 'grid', gap: 2 }}>
                <dt style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)', fontSize: 13 }}>
                  {row.label}
                </dt>
                <dd
                  style={{
                    margin: 0,
                    color: values[row.key] ? 'var(--jx-text)' : 'var(--jx-text-4)',
                    fontFamily: 'var(--jx-font-sans)',
                  }}
                >
                  {values[row.key] || 'Не заполнено'}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
        <JxButton
          variant="ghost"
          type="button"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

